begin;

on conflict (source_id, original_url) do update
set
  title = excluded.title,
  published_at = excluded.published_at,
  scraped_at = excluded.scraped_at;

select *
from (values
  ('library', 'success', 10, null, '2026-08-25T07:54:33.548Z'::timestamptz, '2026-08-25T07:54:45.727Z'::timestamptz),
  ('language-center', 'success', 10, null, '2026-08-25T07:55:10.042Z'::timestamptz, '2026-08-25T07:55:20.150Z'::timestamptz),
  ('industry-center', 'success', 10, null, '2026-08-25T07:56:05.308Z'::timestamptz, '2026-08-25T07:56:54.457Z'::timestamptz)
) as run(source_id, status, item_count, error_message, started_at, finished_at)
where not exists (
  select 1
  from public.crawl_runs existing
  where existing.source_id = run.source_id
    and existing.started_at = run.started_at
    and existing.finished_at = run.finished_at
);

commit;

select source_id, count(*)::int as notice_count
from public.notices
group by source_id
order by source_id;

select source_id, item_count, finished_at
from public.crawl_runs
where status = 'success'
order by finished_at desc
limit 3;
